37	// CreateResult is the machine-readable summary written when --output-json is
38	// set. It is the contract chained scaffolder steps consume; field names are
39	// stable and additive-only.
40	type CreateResult struct {
41		Template  string            `json:"template"`
42		Owner     string            `json:"owner"`
43		Repo      string            `json:"repo"`
44		Version   string            `json:"version"`
45		OutputDir string            `json:"outputDir"`
46		Values    map[string]any    `json:"values"`
