50	func (o *CreateOptions) applyDefaults() {
51		if o.Owner == "" {
52			o.Owner = defaultTemplateOwner
53		}
54		if o.Repo == "" {
55			o.Repo = defaultTemplateRepo
56		}
57		if o.Stdin == nil {
58			o.Stdin = os.Stdin
59		}
60		if o.UserAgent == "" {
61			o.UserAgent = "intropy-cli"
62		}
