65	// Create runs the full scaffold: resolve release, download tarball, extract,
66	// load manifest, resolve values (with optional interactive prompting), render.
67	func Create(ctx context.Context, opts CreateOptions) error {
68		opts.applyDefaults()
69		if err := validateCreateOptions(opts); err != nil {
70			return err
71		}
72	
73		gh := newConfiguredGitHub(opts.HTTP, opts.UserAgent, opts.GitHubBaseURL)
74		tag, err := resolveReleaseTag(ctx, gh, opts.Owner, opts.Repo, opts.Version)
75		if err != nil {
76			return err
77		}
78		fmt.Fprintf(opts.Stderr, "fetching %s/%s@%s\n", opts.Owner, opts.Repo, tag)
79	
80		templateRoot, cleanup, err := downloadTemplate(ctx, gh, opts.Owner, opts.Repo, tag, opts.Template, "intropy-template-*")
81		if err != nil {
82			return err
83		}
84		defer cleanup()
85	
86		tmpl, values, err := prepareCreateTemplate(templateRoot, opts)
87		if err != nil {
88			return err
89		}
90	
91		// Hoisted before rendering so a broken block declaration fails without
92		// touching the output directory.
93		topology, err := topologyFromTemplate(tmpl, values)
94		if err != nil {
95			return err
96		}
97	
98		if err := renderCreateOutput(templateRoot, opts.Template, opts.OutputDir, opts.Force, values); err != nil {
99			return err
100		}
101		fmt.Fprintf(opts.Stderr, "created %s from %s/%s@%s (template %s)\n", opts.OutputDir, opts.Owner, opts.Repo, tag, opts.Template)
102	
103		// The template field is the repo directory name (opts.Template), not
104		// tmpl.Metadata.Name — it is what a later re-fetch needs.
105		if err := WriteScaffold(opts.OutputDir, Scaffold{
106			SchemaVersion: ScaffoldSchemaVersion,
107			Template:      opts.Template,
108			Owner:         opts.Owner,
109			Repo:          opts.Repo,
110			Version:       tag,
111			DataFlow:      dataFlowFromLabels(tmpl.Metadata.Labels),
112			Values:        values,
113			Topology:      topology,
114		}); err != nil {
115			return err
116		}
117	
118		return maybeWriteCreateResult(opts, tmpl, values, tag, topology)
119	}
