145	func renderCreateOutput(templateRoot, templateName, outputDir string, force bool, values map[string]any) error {
146		skelRoot := filepath.Join(templateRoot, templateSkeletonDir)
147		if info, err := os.Stat(skelRoot); err != nil || !info.IsDir() {
148			return fmt.Errorf("template %q is missing %s/ directory", templateName, templateSkeletonDir)
149		}
150		if err := ensureOutputDir(outputDir, force); err != nil {
151			return err
152		}
153		return Render(skelRoot, outputDir, values)
154	}
