156	func maybeWriteCreateResult(opts CreateOptions, tmpl *Template, values map[string]any, tag string, topology *ScaffoldTopology) error {
157		if opts.OutputJSON == "" {
158			return nil
159		}
160	
161		absOut, err := filepath.Abs(opts.OutputDir)
162		if err != nil {
163			absOut = opts.OutputDir
164		}
165		result := CreateResult{
166			Template:  tmpl.Metadata.Name,
167			Owner:     opts.Owner,
168			Repo:      opts.Repo,
169			Version:   tag,
170			OutputDir: absOut,
171			Values:    values,
172			Topology:  topology,
173		}
174		if err := writeOutputJSON(opts.OutputJSON, opts.Stdout, result); err != nil {
175			return fmt.Errorf("write --output-json: %w", err)
176		}
177		return nil
178	}
