180	func writeOutputJSON(path string, stdout io.Writer, r CreateResult) error {
181		data, err := json.MarshalIndent(r, "", "  ")
182		if err != nil {
183			return err
184		}
185		data = append(data, '\n')
186		if path == "-" {
187			_, err := stdout.Write(data)
188			return err
189		}
190		return os.WriteFile(path, data, 0o644)
191	}
