193	// EnsureOutputDir creates dir if missing and refuses to render into a
194	// non-empty directory unless force is set.
195	func EnsureOutputDir(dir string, force bool) error {
196		return ensureOutputDir(dir, force)
197	}
198	
199	func ensureOutputDir(dir string, force bool) error {
200		info, err := os.Stat(dir)
201		switch {
202		case errors.Is(err, os.ErrNotExist):
203			return os.MkdirAll(dir, 0o755)
204		case err != nil:
205			return err
206		case !info.IsDir():
207			return fmt.Errorf("--output %s exists and is not a directory", dir)
208		}
209		entries, err := os.ReadDir(dir)
210		if err != nil {
211			return err
212		}
213		if len(entries) > 0 && !force {
214			return fmt.Errorf("--output %s is not empty (use --force to overwrite)", dir)
215		}
216		return nil
217	}
