219	// validateTemplateName rejects empty names and anything that could escape the
220	// extracted tarball root via filepath.Join (separators, parent refs, hidden
221	// directories). The template argument is user input that we turn directly into
222	// a path segment, so it has to be sanitized.
223	func validateTemplateName(name string) error {
224		if name == "" {
225			return errors.New("template name is required")
226		}
227		if name == "." || name == ".." || strings.HasPrefix(name, ".") {
228			return fmt.Errorf("invalid template name %q", name)
229		}
230		if strings.ContainsAny(name, `/\`) {
231			return fmt.Errorf("invalid template name %q (must be a single path segment)", name)
232		}
233		return nil
234	}
235	
236	func selectPrompter(opts *CreateOptions) Prompter {
237		return AutoPrompter(opts.Stdin, opts.Stderr, opts.NoInput)
238	}
239	
240	// AutoPrompter returns a StdinPrompter when interactive prompting is viable:
241	// noInput is false and stdin is a real terminal. In CI / piped contexts it
242	// returns nil, so Resolve reports a clean "missing required parameter(s)"
243	// error instead of hanging on a read.
244	func AutoPrompter(stdin io.Reader, out io.Writer, noInput bool) Prompter {
245		if noInput {
246			return nil
247		}
248		f, ok := stdin.(*os.File)
249		if !ok || !isTerminal(f.Fd()) {
250			return nil
251		}
252		return NewStdinPrompter(stdin, out)
253	}
