1	package template
2	
3	import (
4		"fmt"
5		"regexp"
6		"strings"
7	)
8	
9	// Block kinds a template may declare via BlockKindLabel. They mirror the
10	// block kinds of the Intropy.Topology DSL (AddExtractor, AddLoader,
11	// AddAggregator, AddTransactionalIntegration).
12	const (
13		blockKindExtractor     = "extractor"
14		blockKindLoader        = "loader"
15		blockKindAggregator    = "aggregator"
16		blockKindTransactional = "transactional-integration"
17	)
18	
19	// Per-kind well-known parameter names (the convention block templates follow,
20	// documented in the template library's CLAUDE.md). A block declares only its
21	// edge shape; the connector transport is deferred and resolved at
22	// `intropy system create`, so it is not a block parameter here:
23	//
24	//	extractor:                 sourceSystem, [connectorName], publishesTopic, [publishesContract]
25	//	loader:                    subscribesTopic, targetSystem, [connectorName]
26	//	aggregator:                subscribesTopics (comma list), [publishesPort], publishesTopic, [publishesContract]
27	//	transactional-integration: providesApi, [providesContract], targetSystem, [connectorName]
28	//	all kinds:                 [consumesApis] (comma list)
29	
30	var (
31		dns1123Name  = regexp.MustCompile(`^[a-z0-9]([-a-z0-9]{0,61}[a-z0-9])?$`)
32		contractName = regexp.MustCompile(`^[A-Z][A-Za-z0-9]*$`)
33	)
34	
35	// topologyFromTemplate hoists a block template's well-known edge parameters
36	// out of the resolved values into the scaffold record's structured topology
37	// section. Returns nil when the template does not carry BlockKindLabel —
38	// non-block templates are unaffected. Unlike dataFlow, an unrecognized kind
39	// is an error rather than "": guessing would silently drop the wiring that
40	// `system create` depends on.
41	func topologyFromTemplate(tmpl *Template, values map[string]any) (*ScaffoldTopology, error) {
42		kind := tmpl.Metadata.Labels[BlockKindLabel]
43		if kind == "" {
44			return nil, nil
45		}
46	
47		b := &blockValues{values: values}
48		topo := &ScaffoldTopology{BlockKind: kind}
49		switch kind {
50		case blockKindExtractor:
51			topo.Connectors = []ScaffoldConnector{b.connector("source", "in")}
52			topo.Publishes = []ScaffoldPublication{b.publication()}
53		case blockKindLoader:
54			topo.Subscribes = []ScaffoldSubscription{{Topic: b.name("subscribesTopic")}}
55			topo.Connectors = []ScaffoldConnector{b.connector("target", "out")}
56		case blockKindAggregator:
57			topo.Subscribes = b.subscriptions("subscribesTopics")
58			pub := b.publication()
59			pub.Port = b.optionalName("publishesPort", "out")
60			topo.Publishes = []ScaffoldPublication{pub}
61		case blockKindTransactional:
62			topo.Provides = []ScaffoldAPI{b.api("providesApi", "providesContract")}
63			topo.Connectors = []ScaffoldConnector{b.connector("target", "out")}
64		default:
65			return nil, fmt.Errorf("template label %s=%q is not a known block kind (want %q, %q, %q or %q)",
66				BlockKindLabel, kind, blockKindExtractor, blockKindLoader, blockKindAggregator, blockKindTransactional)
67		}
68		topo.Consumes = b.consumes("consumesApis")
69	
70		if b.err != nil {
71			return nil, fmt.Errorf("block kind %s: %w", kind, b.err)
72		}
73		return topo, nil
74	}
75	
76	// blockValues reads the well-known parameters out of the resolved value map,
77	// accumulating the first validation error so call sites stay linear.
78	type blockValues struct {
79		values map[string]any
80		err    error
81	}
82	
83	func (b *blockValues) fail(err error) {
84		if b.err == nil {
85			b.err = err
86		}
87	}
88	
89	func (b *blockValues) str(key string) string {
90		s, _ := b.values[key].(string)
91		return strings.TrimSpace(s)
92	}
93	
94	// name returns a required DNS-1123 parameter.
95	func (b *blockValues) name(key string) string {
96		v := b.str(key)
97		switch {
98		case v == "":
99			b.fail(fmt.Errorf("missing required parameter %q", key))
100		case !dns1123Name.MatchString(v):
101			b.fail(fmt.Errorf("parameter %s=%q is not a valid DNS-1123 name", key, v))
102		}
103		return v
104	}
105	
106	// optionalName returns a DNS-1123 parameter, or fallback when unset.
107	func (b *blockValues) optionalName(key, fallback string) string {
108		v := b.str(key)
109		if v == "" {
110			return fallback
111		}
112		if !dns1123Name.MatchString(v) {
113			b.fail(fmt.Errorf("parameter %s=%q is not a valid DNS-1123 name", key, v))
114		}
115		return v
116	}
117	
118	// contract returns the contract record name for key, defaulting to the
119	// PascalCase form of def (a topic or API name).
120	func (b *blockValues) contract(key, def string) string {
121		v := b.str(key)
122		if v == "" {
123			return pascalCase(def)
124		}
125		if !contractName.MatchString(v) {
126			b.fail(fmt.Errorf("parameter %s=%q is not a valid contract record name (want PascalCase)", key, v))
127		}
128		return v
129	}
130	
131	// connector reads <prefix>System and the shared connectorName parameter
132	// (defaulting to the external system's name). The transport is deferred — a
133	// block declares only what it connects to; how it is reached is resolved at
134	// `intropy system create`, so Transport is left empty (unresolved) here.
135	func (b *blockValues) connector(prefix, direction string) ScaffoldConnector {
136		system := b.name(prefix + "System")
137		return ScaffoldConnector{
138			Name:           b.optionalName("connectorName", system),
139			ExternalSystem: system,
140			Direction:      direction,
141		}
142	}
143	
144	func (b *blockValues) publication() ScaffoldPublication {
145		topic := b.name("publishesTopic")
146		return ScaffoldPublication{
147			Topic:    topic,
148			Contract: b.contract("publishesContract", topic),
149		}
150	}
151	
152	func (b *blockValues) api(nameKey, contractKey string) ScaffoldAPI {
153		api := b.name(nameKey)
154		return ScaffoldAPI{API: api, Contract: b.contract(contractKey, api)}
155	}
156	
157	// subscriptions splits a required comma-separated topic list.
158	func (b *blockValues) subscriptions(key string) []ScaffoldSubscription {
159		topics := b.list(key)
160		if len(topics) == 0 {
161			b.fail(fmt.Errorf("missing required parameter %q", key))
162			return nil
163		}
164		subs := make([]ScaffoldSubscription, 0, len(topics))
165		for _, t := range topics {
166			if !dns1123Name.MatchString(t) {
167				b.fail(fmt.Errorf("parameter %s: %q is not a valid DNS-1123 topic name", key, t))
168			}
169			subs = append(subs, ScaffoldSubscription{Topic: t})
170		}
171		return subs
172	}
173	
174	// consumes splits an optional comma-separated API list. Contracts stay empty:
175	// they are recorded on the providing side.
176	func (b *blockValues) consumes(key string) []ScaffoldAPI {
177		names := b.list(key)
178		if len(names) == 0 {
179			return nil
180		}
181		apis := make([]ScaffoldAPI, 0, len(names))
182		for _, n := range names {
183			if !dns1123Name.MatchString(n) {
184				b.fail(fmt.Errorf("parameter %s: %q is not a valid DNS-1123 API name", key, n))
185			}
186			apis = append(apis, ScaffoldAPI{API: n})
187		}
188		return apis
189	}
190	
191	func (b *blockValues) list(key string) []string {
192		var out []string
193		for _, part := range strings.Split(b.str(key), ",") {
194			if p := strings.TrimSpace(part); p != "" {
195				out = append(out, p)
196			}
197		}
198		return out
199	}
200	
201	// pascalCase turns a DNS-1123 name into a C# type name: "order-raw" -> "OrderRaw".
202	func pascalCase(name string) string {
203		var sb strings.Builder
204		for _, seg := range strings.Split(name, "-") {
205			if seg == "" {
206				continue
207			}
208			sb.WriteString(strings.ToUpper(seg[:1]))
209			sb.WriteString(seg[1:])
210		}
211		return sb.String()
212	}
