40		HostDir      string `json:"hostDir"`
41		ContractsDir string `json:"contractsDir"`
42		Graph
43	}
44	
45	// Create scaffolds a SystemHost from the scaffold records of the components
46	// under opts.Dir: discover → join the edge graph → render the system-host
47	// template → generate the topology and contracts files → link the Contracts
48	// project into each component csproj.
49	func Create(ctx context.Context, opts CreateOptions) error {
50		if opts.Dir == "" {
51			opts.Dir = "."
52		}
53		if !dns1123Name.MatchString(opts.SystemName) {
54			return fmt.Errorf("system name %q is not a valid DNS-1123 name", opts.SystemName)
55		}
56		projectName := pascalCase(opts.SystemName)
57		systemClass := projectName + "System"
58		// A fixed, system-independent pub/sub component name. A scaffolded component runs standalone
59		// against its own local/dapr-components (an in-memory "pubsub"); the SystemHost overrides that
60		// folder at run time with a Redis-backed "pubsub". The same worker binary binds to the same
61		// component name in both, so the name must not vary per system.
62		pubsub := pubsubComponentName
63		hostDir := filepath.Join(opts.Dir, projectName+".SystemHost")
64		contractsDir := filepath.Join(opts.Dir, projectName+".Contracts")
65	
66		discovery, err := Discover(opts.Dir)
67		if err != nil {
68			return err
69		}
70		graph, err := BuildGraph(opts.SystemName, pubsub, discovery.Components)
71		if err != nil {
72			return err
73		}
74		graph.Warnings = append(discovery.Warnings, graph.Warnings...)
75		if len(graph.Components) == 0 {
76			graph.Warnings = append(graph.Warnings,
77				fmt.Sprintf("no components found under %s — the SystemHost is created with an empty Define()", opts.Dir))
78		}
79	
80		// Resolve deferred connector transports: a block declares only what it connects to, so any
81		// connector may reach here without a transport. Prompt for each (interactive only); a
82		// non-interactive run leaves them unresolved (the generated Connectors.cs still compiles).
83		if err := resolveConnectorTransports(opts, &graph); err != nil {
84			return err
85		}
86	
87		// The template renders the static host skeleton (csproj, Program.cs,
88		// AGENTS.md) and records the host's own scaffold provenance; the
89		// graph-derived files are written on top afterwards.
90		if err := template.Create(ctx, template.CreateOptions{
91			Template:      systemHostTemplate,
92			OutputDir:     hostDir,
93			Version:       opts.Version,
94			SetValues:     map[string]any{"name": opts.SystemName},
95			Force:         opts.Force,
96			NoInput:       true,
97			Stdin:         opts.Stdin,
98			Stdout:        opts.Stdout,
99			Stderr:        opts.Stderr,
100			HTTP:          opts.HTTP,
101			UserAgent:     opts.UserAgent,
102			Owner:         opts.Owner,
103			Repo:          opts.Repo,
104			GitHubBaseURL: opts.GitHubBaseURL,
105		}); err != nil {
106			return err
107		}
108	
109		if err := writeFiles(hostDir, HostFiles(graph, projectName, systemClass)); err != nil {
110			return err
111		}
112		if err := template.EnsureOutputDir(contractsDir, opts.Force); err != nil {
113			return err
114		}
115		if err := writeFiles(contractsDir, ContractsFiles(graph, projectName)); err != nil {
116			return err
117		}
118	
119		if !opts.NoLinkContracts {
120			linkWarnings := linkContracts(discovery.Components, projectName)
121			graph.Warnings = append(graph.Warnings, linkWarnings...)
122		}
123	
124		for _, w := range graph.Warnings {
125			fmt.Fprintf(opts.Stderr, "warning: %s\n", w)
126		}
127		fmt.Fprintf(opts.Stderr, "created %s (%d components, %d topics, %d apis, %d connectors)\n",
128			hostDir, len(graph.Components), len(graph.Topics), len(graph.APIs), len(graph.Connectors))
129		fmt.Fprintf(opts.Stderr, "next: dotnet run --project %s -- check\n", hostDir)
130	
131		return maybeWriteResult(opts, CreateResult{
132			ProjectName:  projectName,
133			HostDir:      hostDir,
134			ContractsDir: contractsDir,
135			Graph:        graph,
136		})
137	}
