139	func writeFiles(dir string, files map[string]string) error {
140		for _, name := range sortedKeys(files) {
141			if err := os.WriteFile(filepath.Join(dir, name), []byte(files[name]), 0o644); err != nil {
142				return err
143			}
144		}
145		return nil
146	}
147	
148	// resolveConnectorTransports fills in the transport of every connector that
149	// reached the graph without one. In an interactive run it prompts for each,
150	// offering only transports valid for the direction(s) the connector is used in
151	// (Dapr's HTTP binding is output-only, so it is not offered for a read/From
152	// connector — mirroring the DSL's ITP105/ITP106). In a non-interactive run
153	// (--no-input, --output-json, or no TTY) it leaves them unresolved and warns;
154	// the generated Connectors.cs still compiles via the transport-less overload,
155	// and the topology validates with an ITP107 warning.
156	func resolveConnectorTransports(opts CreateOptions, g *Graph) error {
157		var unresolved []int
158		for i := range g.Connectors {
159			if g.Connectors[i].Transport == "" {
160				unresolved = append(unresolved, i)
161			}
162		}
163		if len(unresolved) == 0 {
164			return nil
165		}
166	
167		prompter := template.AutoPrompter(opts.Stdin, opts.Stderr, opts.NoInput || opts.OutputJSON != "")
168		if prompter == nil {
169			for _, i := range unresolved {
170				g.Warnings = append(g.Warnings, fmt.Sprintf(
171					"connector %q has no transport — left unresolved; set it by re-running 'intropy system create' interactively",
172					g.Connectors[i].Name))
173			}
174			return nil
175		}
176	
177		fmt.Fprintln(opts.Stderr, "Some connectors have no transport yet — choose how each reaches its external system:")
178		for _, i := range unresolved {
179			c := &g.Connectors[i]
180			field := template.FieldSpec{
181				Name:        c.Name + "Transport",
182				Title:       fmt.Sprintf("Transport for connector %q (external system %q)", c.Name, c.ExternalSystem),
183				Description: "selects the Dapr binding type",
184				Type:        "string",
185				Enum:        transportOptions(validTransports(c.directions)),
186			}
187			v, err := prompter.Prompt(field)
188			if err != nil {
189				return fmt.Errorf("resolving transport for connector %q: %w", c.Name, err)
190			}
191			if s, ok := v.(string); ok {
192				c.Transport = s
193			}
194		}
195		return nil
196	}
197	
198	// validTransports returns the transports whose Dapr binding type supports every
199	// direction the connector is used in. Reading (From/"in") needs an input-capable
200	// transport, so http (output-only) is excluded whenever the connector is read.
201	func validTransports(directions map[string]bool) []string {
202		all := []string{"sftp", "http", "blob"}
203		if !directions["in"] {
204			return all
205		}
206		valid := make([]string, 0, len(all))
207		for _, t := range all {
208			if t == "http" {
209				continue
210			}
211			valid = append(valid, t)
212		}
213		return valid
214	}
215	
216	func transportOptions(ss []string) []any {
217		out := make([]any, len(ss))
218		for i, s := range ss {
219			out[i] = s
220		}
221		return out
222	}
223	
224	// linkContracts inserts a ProjectReference to the shared Contracts project
225	// into each component csproj that lacks one. The insertion is conservative
226	// plain-text surgery before the closing </Project> tag; anything unexpected
227	// becomes a warning, never a failure.
228	func linkContracts(components []Component, projectName string) (warnings []string) {
229		ref := fmt.Sprintf("../%s.Contracts/%s.Contracts.csproj", projectName, projectName)
230		itemGroup := fmt.Sprintf("    <ItemGroup>\n        <ProjectReference Include=%q />\n    </ItemGroup>\n", ref)
231	
232		for _, c := range components {
233			path := filepath.Join(c.Dir, c.Name+".csproj")
234			data, err := os.ReadFile(path)
235			if err != nil {
236				warnings = append(warnings, fmt.Sprintf("could not link Contracts into %s: %v", path, err))
237				continue
238			}
239			if bytes.Contains(data, []byte(projectName+".Contracts.csproj")) {
240				continue
241			}
242			idx := bytes.LastIndex(data, []byte("</Project>"))
243			if idx < 0 {
244				warnings = append(warnings, fmt.Sprintf("could not link Contracts into %s: no </Project> element", path))
245				continue
246			}
247			var out bytes.Buffer
248			out.Write(data[:idx])
249			out.WriteString(itemGroup)
250			out.Write(data[idx:])
251			if err := os.WriteFile(path, out.Bytes(), 0o644); err != nil {
252				warnings = append(warnings, fmt.Sprintf("could not link Contracts into %s: %v", path, err))
253			}
254		}
255		return warnings
256	}
257	
258	func maybeWriteResult(opts CreateOptions, result CreateResult) error {
259		if opts.OutputJSON == "" {
260			return nil
261		}
262		data, err := json.MarshalIndent(result, "", "  ")
263		if err != nil {
264			return err
265		}
266		data = append(data, '\n')
267		if opts.OutputJSON == "-" {
268			_, err := opts.Stdout.Write(data)
269			return err
270		}
271		if err := os.WriteFile(opts.OutputJSON, data, 0o644); err != nil {
272			return fmt.Errorf("write --output-json: %w", err)
273		}
274		return nil
275	}
