2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7	
8		"github.com/integrio-intropy/intropy-cli/internal/template"
9	)
10	
11	// Graph is the joined system topology derived from the components' scaffold
12	// records: the input to codegen and the shape reported via --output-json.
13	// Join rules: same topic name across records ⇒ one shared topic; an API name
14	// provided by one component and consumed by others ⇒ one shared API; same
15	// connector name with the same external system and transport ⇒ one shared
16	// connector. Warnings become TODO comments in the generated code; only
17	// conflicts a comment cannot fix (two providers, contradictory connectors)
18	// fail the build of the graph.
19	type Graph struct {
20		System     string           `json:"system"`
21		Pubsub     string           `json:"pubsub"`
22		Components []GraphComponent `json:"components"`
23		Topics     []Topic          `json:"topics"`
24		APIs       []API            `json:"apis"`
25		Connectors []Connector      `json:"connectors"`
26		Warnings   []string         `json:"warnings,omitempty"`
27	}
28	
29	// GraphComponent is one component as it will be declared in Define().
30	type GraphComponent struct {
31		Name string `json:"name"`
32		// Kind is the block kind driving the Add<Kind> call. For legacy
33		// components (scaffolded without topology metadata) it is inferred from
34		// the dataFlow record and the declaration is emitted bare with a TODO.
35		Kind     string                     `json:"kind"`
36		Legacy   bool                       `json:"legacy,omitempty"`
37		Topology *template.ScaffoldTopology `json:"-"`
38	}
39	
40	// Topic is one shared system topic.
41	type Topic struct {
42		Name        string   `json:"name"`
43		Contract    string   `json:"contract"`
44		Field       string   `json:"-"` // C# field name in Topics.cs
45		Publishers  []string `json:"publishers,omitempty"`
46		Subscribers []string `json:"subscribers,omitempty"`
47		// Todo carries a per-topic warning emitted as a TODO comment on the field.
48		Todo string `json:"-"`
49	}
50	
51	// API is one shared synchronous API.
52	type API struct {
53		Name      string   `json:"name"`
54		Contract  string   `json:"contract"`
55		Field     string   `json:"-"`
56		Provider  string   `json:"provider,omitempty"`
57		Consumers []string `json:"consumers,omitempty"`
58		Todo      string   `json:"-"`
59	}
60	
61	// Connector is one shared connection point to an external system.
62	type Connector struct {
63		Name           string `json:"name"`
64		ExternalSystem string `json:"externalSystem"`
65		Transport      string `json:"transport"`
66		Field          string `json:"-"`
67		declaredBy     string
68		// directions is the set of directions ("in"/"out") the connector is used in
69		// across components — used to offer only capability-valid transports when
70		// prompting for an unresolved transport at `system create`.
71		directions map[string]bool
72	}
73	
74	const blockKindTransactional = "transactional-integration"
75	
76	// BuildGraph joins the discovered components into a Graph. Components stay in
77	// discovery (lexical) order; topics, APIs, and connectors are sorted by name.
78	func BuildGraph(systemName, pubsub string, components []Component) (Graph, error) {
79		g := Graph{System: systemName, Pubsub: pubsub}
80		topics := map[string]*Topic{}
81		apis := map[string]*API{}
82		connectors := map[string]*Connector{}
83	
84		for _, c := range components {
85			topo := c.Scaffold.Topology
86			if topo == nil {
87				g.Components = append(g.Components, GraphComponent{
88					Name:   c.Name,
89					Kind:   legacyKind(c.Scaffold.DataFlow),
90					Legacy: true,
91				})
92				continue
93			}
94			g.Components = append(g.Components, GraphComponent{Name: c.Name, Kind: topo.BlockKind, Topology: topo})
95	
96			for _, pub := range topo.Publishes {
97				t := ensureTopic(topics, pub.Topic)
98				t.Publishers = append(t.Publishers, c.Name)
99				contract := orPascal(pub.Contract, pub.Topic)
100				switch {
101				case t.Contract == "":
102					t.Contract = contract
103				case t.Contract != contract:
104					note := fmt.Sprintf("topic %q: publishers disagree on the contract (%s vs %s) — first publisher wins", pub.Topic, t.Contract, contract)
105					g.Warnings = append(g.Warnings, note)
106					t.Todo = fmt.Sprintf("contract mismatch: %s vs %s (first publisher wins)", t.Contract, contract)
107				}
108			}
109			for _, sub := range topo.Subscribes {
110				t := ensureTopic(topics, sub.Topic)
111				t.Subscribers = append(t.Subscribers, c.Name)
112			}
113			for _, p := range topo.Provides {
114				a := ensureAPI(apis, p.API)
115				if a.Provider != "" {
116					return Graph{}, fmt.Errorf(
117						"API %q is provided by both %q and %q — an API has exactly one provider (ITP501); rename one via --set providesApi=",
118						p.API, a.Provider, c.Name)
119				}
120				a.Provider = c.Name
121				a.Contract = orPascal(p.Contract, p.API)
122			}
123			for _, con := range topo.Consumes {
124				a := ensureAPI(apis, con.API)
125				a.Consumers = append(a.Consumers, c.Name)
126			}
127			for _, cn := range topo.Connectors {
128				if existing, ok := connectors[cn.Name]; ok {
129					if existing.ExternalSystem != cn.ExternalSystem {
130						return Graph{}, fmt.Errorf(
131							"connector %q is declared against %q by %q but %q by %q — re-scaffold one with --set connectorName= or edit its scaffold.json",
132							cn.Name, existing.ExternalSystem, existing.declaredBy,
133							cn.ExternalSystem, c.Name)
134					}
135					// Only resolved transports can conflict; an empty one is deferred, not conflicting.
136					// A resolved value anywhere resolves the shared connector (first resolved wins).
137					if cn.Transport != "" && existing.Transport != "" && existing.Transport != cn.Transport {
138						return Graph{}, fmt.Errorf(
139							"connector %q is declared with transport %q by %q but %q by %q — re-scaffold one with --set connectorName= or edit its scaffold.json",
140							cn.Name, existing.Transport, existing.declaredBy, cn.Transport, c.Name)
141					}
142					if existing.Transport == "" && cn.Transport != "" {
143						existing.Transport = cn.Transport
144					}
145					if cn.Direction != "" {
146						existing.directions[cn.Direction] = true
147					}
148					continue
149				}
150				connectors[cn.Name] = &Connector{
151					Name:           cn.Name,
152					ExternalSystem: cn.ExternalSystem,
153					Transport:      cn.Transport,
154					Field:          pascalCase(cn.Name),
155					declaredBy:     c.Name,
156					directions:     directionSet(cn.Direction),
157				}
158			}
159		}
160	
161		for _, name := range sortedKeys(topics) {
162			t := topics[name]
163			if t.Contract == "" {
164				t.Contract = pascalCase(name)
165			}
166			if len(t.Publishers) == 0 {
167				g.Warnings = append(g.Warnings, fmt.Sprintf("topic %q has subscribers but no publisher", name))
168				t.Todo = "no component publishes this topic yet"
169			}
170			g.Topics = append(g.Topics, *t)
171		}
172		for _, name := range sortedKeys(apis) {
173			a := apis[name]
174			if a.Contract == "" {
175				a.Contract = pascalCase(name)
176			}
177			if a.Provider == "" {
178				g.Warnings = append(g.Warnings, fmt.Sprintf("API %q is consumed but no component provides it (Build() will raise ITP501)", name))
179				a.Todo = "no component provides this API yet (ITP501)"
180			}
181			g.APIs = append(g.APIs, *a)
182		}
183		for _, name := range sortedKeys(connectors) {
184			g.Connectors = append(g.Connectors, *connectors[name])
185		}
186		return g, nil
187	}
188	
189	// directionSet seeds a connector's direction set from its first usage.
190	func directionSet(direction string) map[string]bool {
191		m := map[string]bool{}
192		if direction != "" {
193			m[direction] = true
194		}
195		return m
196	}
197	
198	func ensureTopic(topics map[string]*Topic, name string) *Topic {
199		if t, ok := topics[name]; ok {
200			return t
201		}
202		t := &Topic{Name: name, Field: pascalCase(name)}
203		topics[name] = t
204		return t
205	}
206	
207	func ensureAPI(apis map[string]*API, name string) *API {
208		if a, ok := apis[name]; ok {
209			return a
210		}
211		a := &API{Name: name, Field: pascalCase(name)}
212		apis[name] = a
213		return a
214	}
215	
216	// legacyKind maps the dataFlow of a component scaffolded without topology
217	// metadata onto the closest block kind, so it can at least be declared.
218	func legacyKind(dataFlow string) string {
219		switch dataFlow {
220		case "in":
221			return "extractor"
222		case "out":
223			return "loader"
224		case "internal":
225			return "aggregator"
226		default:
227			return blockKindTransactional
228		}
229	}
230	
231	func sortedKeys[V any](m map[string]V) []string {
232		keys := make([]string, 0, len(m))
233		for k := range m {
234			keys = append(keys, k)
235		}
236		sort.Strings(keys)
237		return keys
238	}
239	
240	func orPascal(contract, name string) string {
241		if contract != "" {
242			return contract
243		}
244		return pascalCase(name)
245	}
246	
247	// pascalCase turns a DNS-1123 name into a C# identifier: "order-raw" -> "OrderRaw".
248	func pascalCase(name string) string {
249		var sb strings.Builder
250		for _, seg := range strings.Split(name, "-") {
251			if seg == "" {
252				continue
253			}
254			sb.WriteString(strings.ToUpper(seg[:1]))
255			sb.WriteString(seg[1:])
256		}
257		return sb.String()
258	}
