18	
19	// HostFiles returns the generated files of the SystemHost project, keyed by
20	// file name. Ref files (Topics.cs, Apis.cs, Connectors.cs) are only emitted
21	// when non-empty.
22	func HostFiles(g Graph, projectName, systemClass string) map[string]string {
23		files := map[string]string{
24			systemClass + ".cs": systemDefinition(g, projectName, systemClass),
25		}
26		if len(g.Topics) > 0 {
27			files["Topics.cs"] = topicsFile(g, projectName)
28		}
29		if len(g.APIs) > 0 {
30			files["Apis.cs"] = apisFile(g, projectName)
31		}
32		if len(g.Connectors) > 0 {
33			files["Connectors.cs"] = connectorsFile(g, projectName)
34		}
35		return files
36	}
