53	func systemDefinition(g Graph, projectName, systemClass string) string {
54		var b strings.Builder
55		b.WriteString(generatedHeader)
56		b.WriteString("using Intropy.Topology;\n\n")
57		fmt.Fprintf(&b, "namespace %s.SystemHost;\n\n", projectName)
58		b.WriteString("// The discoverable system definition. SystemDiscovery finds this one ISystemDefinition in the\n")
59		b.WriteString("// SystemHost assembly, builds + validates its topology, and both backends (Aspire run,\n")
60		b.WriteString("// generate/check) consume the result.\n")
61		fmt.Fprintf(&b, "public sealed class %s : ISystemDefinition\n{\n", systemClass)
62		fmt.Fprintf(&b, "    public string SystemName => %q;\n\n", g.System)
63		b.WriteString("    public void Define(SystemBuilder builder)\n    {\n")
64		if len(g.Components) == 0 {
65			b.WriteString("        // TODO(intropy): no components found next to this SystemHost yet. Scaffold them with\n")
66			b.WriteString("        // `intropy int create block-*` and declare each one here.\n")
67		}
68		for i, c := range g.Components {
69			if i > 0 {
70				b.WriteString("\n")
71			}
72			writeComponent(&b, g, c)
73		}
74		b.WriteString("    }\n}\n")
75		return b.String()
76	}
