78	func writeComponent(b *strings.Builder, g Graph, c GraphComponent) {
79		if c.Legacy {
80			fmt.Fprintf(b, "        // TODO(intropy): %s was scaffolded without topology metadata — wire its edges\n", c.Name)
81			b.WriteString("        // (From/To/Publishes/Subscribes/Provides) manually.\n")
82			fmt.Fprintf(b, "        builder.%s(%q);\n", addMethod[c.Kind], c.Name)
83			return
84		}
85	
86		var calls []string
87		topo := c.Topology
88		switch c.Kind {
89		case "extractor":
90			for _, cn := range topo.Connectors {
91				calls = append(calls, fmt.Sprintf(".From(Connectors.%s)", pascalCase(cn.Name)))
92			}
93			for _, p := range topo.Publishes {
94				calls = append(calls, fmt.Sprintf(".Publishes(Topics.%s)", pascalCase(p.Topic)))
95			}
96		case "aggregator":
97			fields := make([]string, 0, len(topo.Subscribes))
98			for _, s := range topo.Subscribes {
99				fields = append(fields, "Topics."+pascalCase(s.Topic))
100			}
101			calls = append(calls, fmt.Sprintf(".Subscribes(%s)", strings.Join(fields, ", ")))
102			for _, p := range topo.Publishes {
103				calls = append(calls, fmt.Sprintf(".Publishes(%q, Topics.%s)", p.Port, pascalCase(p.Topic)))
104			}
105		case "loader":
106			for _, s := range topo.Subscribes {
107				calls = append(calls, fmt.Sprintf(".Subscribes(Topics.%s)", pascalCase(s.Topic)))
108			}
109			for _, cn := range topo.Connectors {
110				calls = append(calls, fmt.Sprintf(".To(Connectors.%s)", pascalCase(cn.Name)))
111			}
112		case blockKindTransactional:
113			for _, p := range topo.Provides {
114				calls = append(calls, fmt.Sprintf(".Provides(Apis.%s)", pascalCase(p.API)))
115			}
116			for _, cn := range topo.Connectors {
117				calls = append(calls, fmt.Sprintf(".To(Connectors.%s)", pascalCase(cn.Name)))
118			}
119		}
120		for _, con := range topo.Consumes {
121			calls = append(calls, fmt.Sprintf(".Consumes(Apis.%s)", pascalCase(con.API)))
122		}
123	
124		fmt.Fprintf(b, "        builder.%s(%q)", addMethod[c.Kind], c.Name)
125		for _, call := range calls {
126			b.WriteString("\n            ")
127			b.WriteString(call)
128		}
129		b.WriteString(";\n")
130	}
