132	func topicsFile(g Graph, projectName string) string {
133		var b strings.Builder
134		b.WriteString(generatedHeader)
135		b.WriteString("using Intropy.Topology;\n")
136		fmt.Fprintf(&b, "using %s.Contracts;\n\n", projectName)
137		fmt.Fprintf(&b, "namespace %s.SystemHost;\n\n", projectName)
138		b.WriteString("// System-internal topics, declared as static fields. The backing pubsub resource materializes\n")
139		b.WriteString("// from usage — publishing to or subscribing to a topic is what brings it into the model.\n")
140		b.WriteString("public static class Topics\n{\n")
141		for i, t := range g.Topics {
142			if i > 0 {
143				b.WriteString("\n")
144			}
145			if t.Todo != "" {
146				fmt.Fprintf(&b, "    // TODO(intropy): %s.\n", t.Todo)
147			}
148			fmt.Fprintf(&b, "    public static readonly TopicRef<%s> %s =\n", t.Contract, t.Field)
149			fmt.Fprintf(&b, "        TopicRef<%s>.Define(%q, %q);\n", t.Contract, g.Pubsub, t.Name)
150		}
151		b.WriteString("}\n")
152		return b.String()
153	}
