178	func connectorsFile(g Graph, projectName string) string {
179		var b strings.Builder
180		b.WriteString(generatedHeader)
181		b.WriteString("using Intropy.Topology;\n\n")
182		fmt.Fprintf(&b, "namespace %s.SystemHost;\n\n", projectName)
183		b.WriteString("// Connectors: the named connection points between this system and the external systems it\n")
184		b.WriteString("// talks to. The transport selects the Dapr binding type; direction follows from usage (From/To).\n")
185		b.WriteString("// A connector with no transport is unresolved — resolve it by re-running `intropy system create`.\n")
186		b.WriteString("public static class Connectors\n{\n")
187		for i, c := range g.Connectors {
188			if i > 0 {
189				b.WriteString("\n")
190			}
191			fmt.Fprintf(&b, "    public static readonly ConnectorRef %s =\n", c.Field)
192			if c.Transport == "" {
193				// Unresolved: emit the transport-less overload. The DSL builds and validates it with an
194				// ITP107 warning; running/generating still needs it resolved.
195				fmt.Fprintf(&b, "        ConnectorRef.Define(%q, new ExternalSystem(%q));\n",
196					c.Name, c.ExternalSystem)
197				continue
198			}
199			fmt.Fprintf(&b, "        ConnectorRef.Define(%q, new ExternalSystem(%q), Transport.%s());\n",
200				c.Name, c.ExternalSystem, transportMethod(c.Transport))
201		}
202		b.WriteString("}\n")
203		return b.String()
204	}
