206	func contractsFile(g Graph, projectName string) string {
207		// One stub record per distinct contract, across topics and APIs.
208		seen := map[string]bool{}
209		for _, t := range g.Topics {
210			seen[t.Contract] = true
211		}
212		for _, a := range g.APIs {
213			seen[a.Contract] = true
214		}
215		contracts := make([]string, 0, len(seen))
216		for c := range seen {
217			contracts = append(contracts, c)
218		}
219		sort.Strings(contracts)
220	
221		var b strings.Builder
222		b.WriteString(generatedHeader)
223		fmt.Fprintf(&b, "namespace %s.Contracts;\n\n", projectName)
224		b.WriteString("// The contract records carried on the system's topics and APIs, shared by the SystemHost's\n")
225		b.WriteString("// typed refs and every component project.\n")
226		if len(contracts) == 0 {
227			b.WriteString("\n// TODO(intropy): no contracts yet — they appear here as components declare topics and APIs.\n")
228		}
229		for _, c := range contracts {
230			fmt.Fprintf(&b, "\npublic sealed record %s(); // TODO(intropy): define the payload\n", c)
231		}
232		return b.String()
233	}
