235	func contractsProject(projectName string) string {
236		return fmt.Sprintf(`<Project Sdk="Microsoft.NET.Sdk">
237	    <PropertyGroup>
238	        <TargetFramework>net10.0</TargetFramework>
239	        <Nullable>enable</Nullable>
240	        <RootNamespace>%s.Contracts</RootNamespace>
241	    </PropertyGroup>
242	</Project>
243	`, projectName)
244	}
