246	// transportMethod maps a resolved transport ("http"/"sftp"/"blob") to its
247	// Transport factory method. Unresolved (empty) connectors never reach here —
248	// connectorsFile emits the transport-less overload for them.
249	func transportMethod(transport string) string {
250		return strings.ToUpper(transport[:1]) + transport[1:]
251	}
