39	func buildTarGz(t *testing.T, prefix string, entries map[string]string) []byte {
40		t.Helper()
41		var buf bytes.Buffer
42		gz := gzip.NewWriter(&buf)
43		tw := tar.NewWriter(gz)
44		for name, content := range entries {
45			full := prefix + "/" + name
46			h := &tar.Header{Name: full, Mode: 0o644, Size: int64(len(content)), Typeflag: tar.TypeReg}
47			if err := tw.WriteHeader(h); err != nil {
48				t.Fatal(err)
49			}
50			if _, err := tw.Write([]byte(content)); err != nil {
51				t.Fatal(err)
52			}
53		}
54		if err := tw.Close(); err != nil {
55			t.Fatal(err)
56		}
57		if err := gz.Close(); err != nil {
58			t.Fatal(err)
59		}
60		return buf.Bytes()
61	}
