package system

import (
	"fmt"
	"regexp"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// Block kinds a component may declare via template.BlockKindLabel, recorded in
// its scaffold as Scaffold.BlockKind. They mirror the block kinds of the
// Intropy.Topology DSL (AddExtractor, AddLoader, AddAggregator,
// AddTransactionalIntegration); blockKindTransactional lives in graph.go.
const (
	blockKindExtractor  = "extractor"
	blockKindLoader     = "loader"
	blockKindAggregator = "aggregator"
)

// Per-kind well-known parameter names (the convention block templates follow,
// documented in the template library's CLAUDE.md). A block declares only its
// edge shape; the connector transport is deferred and resolved here at `system
// create`, so it is not a scaffold value:
//
//	extractor:                 sourceSystem, [connectorName], publishesTopic, [publishesContract]
//	loader:                    subscribesTopic, targetSystem, [connectorName]
//	aggregator:                subscribesTopics (comma list), [publishesPort], publishesTopic, [publishesContract]
//	transactional-integration: providesApi, [providesContract], targetSystem, [connectorName]
//	all kinds:                 [consumesApis] (comma list)

var contractName = regexp.MustCompile(`^[A-Z][A-Za-z0-9]*$`)

// EdgeIntent is the structured edge intent of one block component, derived at
// `system create` from the component's recorded BlockKind and Values. It is an
// intermediate model — BuildGraph joins the EdgeIntents of sibling components
// into the system Graph; nothing persists it.
type EdgeIntent struct {
	BlockKind  string
	Connectors []EdgeConnector
	Publishes  []EdgePublication
	Subscribes []EdgeSubscription
	Provides   []EdgeAPI
	Consumes   []EdgeAPI
}

// EdgeConnector is a connection point to an external system.
type EdgeConnector struct {
	Name           string
	ExternalSystem string
	// Transport is deferred: a block declares only what it connects to and which
	// way data flows; how the external system is reached (the Dapr binding type)
	// is resolved at `system create`. Empty means unresolved.
	Transport string // "http", "sftp", "blob" or "" (unresolved)
	Direction string // "in" or "out"
}

// EdgePublication is a topic the component publishes, with the contract record
// name the payload should be typed as.
type EdgePublication struct {
	Port     string
	Topic    string
	Contract string
}

// EdgeSubscription is a topic the component subscribes to. The contract comes
// from the topic's publisher, so none is recorded here.
type EdgeSubscription struct {
	Topic string
}

// EdgeAPI is a synchronous API the component provides or consumes. The contract
// is only recorded on the providing side.
type EdgeAPI struct {
	API      string
	Contract string
}

// edgesFromScaffold derives a block component's edge intent from its recorded
// BlockKind and resolved Values. Returns nil when the scaffold declares no
// block kind — non-block components have no edges. An unrecognized kind is an
// error rather than nil: guessing would silently drop the wiring the graph
// depends on. This is where the block-kind conventions are interpreted — the
// component itself stays a self-contained record of label + values.
func edgesFromScaffold(s template.Scaffold) (*EdgeIntent, error) {
	kind := strings.TrimSpace(s.BlockKind)
	if kind == "" {
		return nil, nil
	}

	b := &blockValues{values: s.Values}
	e := &EdgeIntent{BlockKind: kind}
	switch kind {
	case blockKindExtractor:
		e.Connectors = []EdgeConnector{b.connector("source", "in")}
		e.Publishes = []EdgePublication{b.publication()}
	case blockKindLoader:
		e.Subscribes = []EdgeSubscription{{Topic: b.name("subscribesTopic")}}
		e.Connectors = []EdgeConnector{b.connector("target", "out")}
	case blockKindAggregator:
		e.Subscribes = b.subscriptions("subscribesTopics")
		pub := b.publication()
		pub.Port = b.optionalName("publishesPort", "out")
		e.Publishes = []EdgePublication{pub}
	case blockKindTransactional:
		e.Provides = []EdgeAPI{b.api("providesApi", "providesContract")}
		e.Connectors = []EdgeConnector{b.connector("target", "out")}
	default:
		return nil, fmt.Errorf("block kind %q is not known (want %q, %q, %q or %q)",
			kind, blockKindExtractor, blockKindLoader, blockKindAggregator, blockKindTransactional)
	}
	e.Consumes = b.consumes("consumesApis")

	if b.err != nil {
		return nil, fmt.Errorf("block kind %s: %w", kind, b.err)
	}
	return e, nil
}

// blockValues reads the well-known parameters out of a scaffold's value map,
// accumulating the first validation error so call sites stay linear.
type blockValues struct {
	values map[string]any
	err    error
}

func (b *blockValues) fail(err error) {
	if b.err == nil {
		b.err = err
	}
}

func (b *blockValues) str(key string) string {
	s, _ := b.values[key].(string)
	return strings.TrimSpace(s)
}

// name returns a required DNS-1123 parameter.
func (b *blockValues) name(key string) string {
	v := b.str(key)
	switch {
	case v == "":
		b.fail(fmt.Errorf("missing required parameter %q", key))
	case !dns1123Name.MatchString(v):
		b.fail(fmt.Errorf("parameter %s=%q is not a valid DNS-1123 name", key, v))
	}
	return v
}

// optionalName returns a DNS-1123 parameter, or fallback when unset.
func (b *blockValues) optionalName(key, fallback string) string {
	v := b.str(key)
	if v == "" {
		return fallback
	}
	if !dns1123Name.MatchString(v) {
		b.fail(fmt.Errorf("parameter %s=%q is not a valid DNS-1123 name", key, v))
	}
	return v
}

// contract returns the contract record name for key, defaulting to the
// PascalCase form of def (a topic or API name).
func (b *blockValues) contract(key, def string) string {
	v := b.str(key)
	if v == "" {
		return pascalCase(def)
	}
	if !contractName.MatchString(v) {
		b.fail(fmt.Errorf("parameter %s=%q is not a valid contract record name (want PascalCase)", key, v))
	}
	return v
}

// connector reads <prefix>System and the shared connectorName parameter
// (defaulting to the external system's name). The transport is deferred — a
// block declares only what it connects to; how it is reached is resolved later
// in `system create`, so Transport is left empty (unresolved) here.
func (b *blockValues) connector(prefix, direction string) EdgeConnector {
	system := b.name(prefix + "System")
	return EdgeConnector{
		Name:           b.optionalName("connectorName", system),
		ExternalSystem: system,
		Direction:      direction,
	}
}

func (b *blockValues) publication() EdgePublication {
	topic := b.name("publishesTopic")
	return EdgePublication{
		Topic:    topic,
		Contract: b.contract("publishesContract", topic),
	}
}

func (b *blockValues) api(nameKey, contractKey string) EdgeAPI {
	api := b.name(nameKey)
	return EdgeAPI{API: api, Contract: b.contract(contractKey, api)}
}

// subscriptions splits a required comma-separated topic list.
func (b *blockValues) subscriptions(key string) []EdgeSubscription {
	topics := b.list(key)
	if len(topics) == 0 {
		b.fail(fmt.Errorf("missing required parameter %q", key))
		return nil
	}
	subs := make([]EdgeSubscription, 0, len(topics))
	for _, t := range topics {
		if !dns1123Name.MatchString(t) {
			b.fail(fmt.Errorf("parameter %s: %q is not a valid DNS-1123 topic name", key, t))
		}
		subs = append(subs, EdgeSubscription{Topic: t})
	}
	return subs
}

// consumes splits an optional comma-separated API list. Contracts stay empty:
// they are recorded on the providing side.
func (b *blockValues) consumes(key string) []EdgeAPI {
	names := b.list(key)
	if len(names) == 0 {
		return nil
	}
	apis := make([]EdgeAPI, 0, len(names))
	for _, n := range names {
		if !dns1123Name.MatchString(n) {
			b.fail(fmt.Errorf("parameter %s: %q is not a valid DNS-1123 API name", key, n))
		}
		apis = append(apis, EdgeAPI{API: n})
	}
	return apis
}

func (b *blockValues) list(key string) []string {
	var out []string
	for _, part := range strings.Split(b.str(key), ",") {
		if p := strings.TrimSpace(part); p != "" {
			out = append(out, p)
		}
	}
	return out
}

