// scaffoldComponent writes a component folder with a csproj and a block
// scaffold record carrying the given block kind and resolved values — exactly
// what `int create` writes. The edges are derived from these at discovery, so
// values must carry the block kind's well-known parameters.
func scaffoldComponent(t *testing.T, root, name, kind string, values map[string]any) {
	t.Helper()
	dir := filepath.Join(root, name)
	if err := os.MkdirAll(filepath.Join(dir, ".intropy"), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, name+".csproj"),
		[]byte("<Project Sdk=\"Microsoft.NET.Sdk.Web\">\n</Project>\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	values["name"] = name
	rec := template.Scaffold{
		SchemaVersion: 1,
		Template:      "block-" + kind,
		Owner:         "integrio-intropy",
		Repo:          "intropy-templates",
		Version:       "v1",
		BlockKind:     kind,
		Values:        values,
	}
	data, _ := json.MarshalIndent(rec, "", "  ")
	if err := os.WriteFile(filepath.Join(dir, ".intropy", "scaffold.json"), data, 0o644); err != nil {
		t.Fatal(err)
	}
}

