package system

import (
	"reflect"
	"strings"
	"testing"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// blockScaffold builds the scaffold record `int create` writes for a block
// component: its declared kind plus the resolved parameter values.
func blockScaffold(kind string, values map[string]any) template.Scaffold {
	return template.Scaffold{BlockKind: kind, Values: values}
}

func TestEdgesFromScaffoldNilWithoutBlockKind(t *testing.T) {
	edges, err := edgesFromScaffold(blockScaffold("", map[string]any{"name": "x"}))
	if err != nil {
		t.Fatalf("edgesFromScaffold: %v", err)
	}
	if edges != nil {
		t.Fatalf("edges = %+v, want nil for a non-block component", edges)
	}
}

func TestEdgesFromScaffoldRejectsUnknownKind(t *testing.T) {
	_, err := edgesFromScaffold(blockScaffold("reconciler", map[string]any{}))
	if err == nil || !strings.Contains(err.Error(), "is not known") {
		t.Fatalf("err = %v, want unknown block kind error", err)
	}
}

func TestEdgesFromScaffoldExtractor(t *testing.T) {
	edges, err := edgesFromScaffold(blockScaffold("extractor", map[string]any{
		"name":           "order-extractor",
		"sourceSystem":   "webshop",
		"publishesTopic": "order-raw",
	}))
	if err != nil {
		t.Fatalf("edgesFromScaffold: %v", err)
	}
	want := &EdgeIntent{
		BlockKind: "extractor",
		Connectors: []EdgeConnector{
			// Transport is deferred to `system create`, so it is empty here.
			{Name: "webshop", ExternalSystem: "webshop", Direction: "in"},
		},
		Publishes: []EdgePublication{
			// Contract defaults to PascalCase of the topic.
			{Topic: "order-raw", Contract: "OrderRaw"},
		},
	}
	if !reflect.DeepEqual(edges, want) {
		t.Errorf("edges = %+v, want %+v", edges, want)
	}
}

func TestEdgesFromScaffoldExtractorOverrides(t *testing.T) {
	edges, err := edgesFromScaffold(blockScaffold("extractor", map[string]any{
		"sourceSystem":      "webshop",
		"connectorName":     "webshop-orders",
		"publishesTopic":    "order-raw",
		"publishesContract": "RawOrder",
		"consumesApis":      "freight-booking, pricing",
	}))
	if err != nil {
		t.Fatalf("edgesFromScaffold: %v", err)
	}
	if edges.Connectors[0].Name != "webshop-orders" {
		t.Errorf("connector name = %q, want explicit connectorName", edges.Connectors[0].Name)
	}
	if edges.Publishes[0].Contract != "RawOrder" {
		t.Errorf("contract = %q, want explicit publishesContract", edges.Publishes[0].Contract)
	}
	wantConsumes := []EdgeAPI{{API: "freight-booking"}, {API: "pricing"}}
	if !reflect.DeepEqual(edges.Consumes, wantConsumes) {
		t.Errorf("consumes = %+v, want %+v", edges.Consumes, wantConsumes)
	}
}

func TestEdgesFromScaffoldLoader(t *testing.T) {
	edges, err := edgesFromScaffold(blockScaffold("loader", map[string]any{
		"subscribesTopic": "order-fulfillment",
		"targetSystem":    "erp",
	}))
	if err != nil {
		t.Fatalf("edgesFromScaffold: %v", err)
	}
	want := &EdgeIntent{
		BlockKind:  "loader",
		Subscribes: []EdgeSubscription{{Topic: "order-fulfillment"}},
		Connectors: []EdgeConnector{
			// Transport is deferred to `system create`, so it is empty here.
			{Name: "erp", ExternalSystem: "erp", Direction: "out"},
		},
	}
	if !reflect.DeepEqual(edges, want) {
		t.Errorf("edges = %+v, want %+v", edges, want)
	}
}

func TestEdgesFromScaffoldAggregator(t *testing.T) {
	edges, err := edgesFromScaffold(blockScaffold("aggregator", map[string]any{
		"subscribesTopics":  "order-raw, stock-raw",
		"publishesPort":     "fulfillment",
		"publishesTopic":    "order-fulfillment",
		"publishesContract": "FulfillmentOrder",
	}))
	if err != nil {
		t.Fatalf("edgesFromScaffold: %v", err)
	}
	want := &EdgeIntent{
		BlockKind:  "aggregator",
		Subscribes: []EdgeSubscription{{Topic: "order-raw"}, {Topic: "stock-raw"}},
		Publishes: []EdgePublication{
			{Port: "fulfillment", Topic: "order-fulfillment", Contract: "FulfillmentOrder"},
		},
	}
	if !reflect.DeepEqual(edges, want) {
		t.Errorf("edges = %+v, want %+v", edges, want)
	}
}

func TestEdgesFromScaffoldAggregatorDefaultsPort(t *testing.T) {
	edges, err := edgesFromScaffold(blockScaffold("aggregator", map[string]any{
		"subscribesTopics": "order-raw",
		"publishesTopic":   "order-enriched",
	}))
	if err != nil {
		t.Fatalf("edgesFromScaffold: %v", err)
	}
	if edges.Publishes[0].Port != "out" {
		t.Errorf("port = %q, want default \"out\"", edges.Publishes[0].Port)
	}
}

func TestEdgesFromScaffoldTransactionalIntegration(t *testing.T) {
	edges, err := edgesFromScaffold(blockScaffold("transactional-integration", map[string]any{
		"providesApi":  "freight-booking",
		"targetSystem": "freight",
	}))
	if err != nil {
		t.Fatalf("edgesFromScaffold: %v", err)
	}
	want := &EdgeIntent{
		BlockKind: "transactional-integration",
		Provides:  []EdgeAPI{{API: "freight-booking", Contract: "FreightBooking"}},
		Connectors: []EdgeConnector{
			// Transport is deferred to `system create`, so it is empty here.
			{Name: "freight", ExternalSystem: "freight", Direction: "out"},
		},
	}
	if !reflect.DeepEqual(edges, want) {
		t.Errorf("edges = %+v, want %+v", edges, want)
	}
}

func TestEdgesFromScaffoldValidation(t *testing.T) {
	cases := []struct {
		name    string
		kind    string
		values  map[string]any
		wantErr string
	}{
		{
			name:    "missing required parameter",
			kind:    "extractor",
			values:  map[string]any{"sourceSystem": "webshop"},
			wantErr: `missing required parameter "publishesTopic"`,
		},
		{
			name: "invalid topic name",
			kind: "extractor",
			values: map[string]any{
				"sourceSystem": "webshop", "publishesTopic": "Order.Raw",
			},
			wantErr: "not a valid DNS-1123 name",
		},
		{
			name: "invalid contract name",
			kind: "extractor",
			values: map[string]any{
				"sourceSystem":   "webshop",
				"publishesTopic": "order-raw", "publishesContract": "rawOrder",
			},
			wantErr: "not a valid contract record name",
		},
		{
			name:    "empty subscription list",
			kind:    "aggregator",
			values:  map[string]any{"subscribesTopics": " , ", "publishesTopic": "out-topic"},
			wantErr: `missing required parameter "subscribesTopics"`,
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			_, err := edgesFromScaffold(blockScaffold(tc.kind, tc.values))
			if err == nil || !strings.Contains(err.Error(), tc.wantErr) {
				t.Fatalf("err = %v, want containing %q", err, tc.wantErr)
			}
		})
	}
}

func TestPascalCase(t *testing.T) {
	cases := map[string]string{
		"order-raw":       "OrderRaw",
		"freight-booking": "FreightBooking",
		"erp":             "Erp",
	}
	for in, want := range cases {
		if got := pascalCase(in); got != want {
			t.Errorf("pascalCase(%q) = %q, want %q", in, got, want)
		}
	}
}

