func TestCreateWritesScaffoldTopologyForBlockTemplate(t *testing.T) {
	srv := newBlockTemplateServer(t, "v3.0.0")
	defer srv.Close()

	outDir := filepath.Join(t.TempDir(), "order-extractor")
	err := Create(context.Background(), CreateOptions{
		Template:  "block-extractor",
		OutputDir: outDir,
		Version:   "v3.0.0",
		SetValues: map[string]any{
			"name":           "order-extractor",
			"sourceSystem":   "webshop",
			"publishesTopic": "order-raw",
		},
		NoInput:       true,
		Stderr:        &bytes.Buffer{},
		HTTP:          srv.Client(),
		Owner:         "o",
		Repo:          "r",
		GitHubBaseURL: srv.URL,
	})
	if err != nil {
		t.Fatalf("Create: %v", err)
	}

	got, err := LoadScaffold(filepath.Join(outDir, filepath.FromSlash(ScaffoldRelPath)))
	if err != nil {
		t.Fatalf("LoadScaffold: %v", err)
	}
	topo := got.Topology
	if topo == nil {
		t.Fatal("scaffold.json has no topology section")
	}
	if topo.BlockKind != "extractor" {
		t.Errorf("BlockKind = %q", topo.BlockKind)
	}
	// Transport is deferred out of the block scaffold — it is empty (unresolved)
	// until `intropy system create` prompts for it.
	if len(topo.Connectors) != 1 || topo.Connectors[0].Name != "webshop" ||
		topo.Connectors[0].Transport != "" || topo.Connectors[0].Direction != "in" {
		t.Errorf("Connectors = %+v", topo.Connectors)
	}
	if len(topo.Publishes) != 1 || topo.Publishes[0].Topic != "order-raw" || topo.Publishes[0].Contract != "OrderRaw" {
		t.Errorf("Publishes = %+v", topo.Publishes)
	}
}

func TestCreateFailsBeforeRenderOnBrokenBlockDeclaration(t *testing.T) {
	srv := newBlockTemplateServer(t, "v3.0.0")
	defer srv.Close()

	outDir := filepath.Join(t.TempDir(), "order-extractor")
	err := Create(context.Background(), CreateOptions{
