		Version:   "v3.0.0",
		SetValues: map[string]any{
			"name":           "order-extractor",
			"sourceSystem":   "webshop",
			"publishesTopic": "Not.A.Topic",
		},
		NoInput:       true,
		Stderr:        &bytes.Buffer{},
		HTTP:          srv.Client(),
		Owner:         "o",
		Repo:          "r",
		GitHubBaseURL: srv.URL,
	})
	if err == nil || !strings.Contains(err.Error(), "DNS-1123") {
		t.Fatalf("err = %v, want DNS-1123 validation error", err)
	}
	if _, statErr := os.Stat(outDir); !os.IsNotExist(statErr) {
		t.Fatalf("failed create should not create output dir, stat err=%v", statErr)
	}
}

