func TestCreateRecordsBlockKindForBlockTemplate(t *testing.T) {
	srv := newBlockTemplateServer(t, "v3.0.0")
	defer srv.Close()

	outDir := filepath.Join(t.TempDir(), "order-extractor")
	err := Create(context.Background(), CreateOptions{
		Template:  "block-extractor",
		OutputDir: outDir,
		Version:   "v3.0.0",
		SetValues: map[string]any{
			"name":           "order-extractor",
			"sourceSystem":   "webshop",
			"publishesTopic": "order-raw",
		},
		NoInput:       true,
		Stderr:        &bytes.Buffer{},
		HTTP:          srv.Client(),
		Owner:         "o",
		Repo:          "r",
		GitHubBaseURL: srv.URL,
	})
	if err != nil {
		t.Fatalf("Create: %v", err)
	}

	got, err := LoadScaffold(filepath.Join(outDir, filepath.FromSlash(ScaffoldRelPath)))
	if err != nil {
		t.Fatalf("LoadScaffold: %v", err)
	}
	// The component stays self-contained: `int create` records only the block
	// kind (from the template label) and the resolved values. The edges are
	// derived later, at `system create` — nothing topology-shaped is written here.
	if got.BlockKind != "extractor" {
		t.Errorf("BlockKind = %q, want extractor", got.BlockKind)
	}
	if got.Values["sourceSystem"] != "webshop" || got.Values["publishesTopic"] != "order-raw" {
		t.Errorf("Values = %+v, want the resolved block parameters preserved", got.Values)
	}
}
